import{z as n,x as B,o as l,c as d,q as i,j as s,D as e,d as t,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Shiller 过度波动","description":"","frontmatter":{"title":"Shiller 过度波动","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/shiller-excess-volatility.md","filePath":"econ/shiller-excess-volatility.md","lastUpdated":1791063341000}'),m={name:"econ/shiller-excess-volatility.md"};function p(h,a,P,c,S,D){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=i('<h1 id="shiller-过度波动" tabindex="-1">Shiller 过度波动 <a class="header-anchor" href="#shiller-过度波动" aria-label="Permalink to &quot;Shiller 过度波动&quot;">​</a></h1><div class="epigraph"><p>若折现率恒定，价格应是未来股利的平滑；观测到的价格比事后实现的现值更抖，恒定折现撑不住。</p><footer>—— Shiller, Do Stock Prices Move Too Much to be Justified by Subsequent Changes in Dividends?, American Economic Review, 1981</footer></div><p><a href="/econ/present-value-identity">上一课</a>从 \\(d-p\\) 推出：股利通道弱则回报必须可预测。本课缺口是同一会计的波动版本：恒定预期回报时，价格是股利的平滑，方差有上界；观测价格往往打破上界。不重写 CS 公式，不把过度波动写成「市场疯狂」的终审。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shiller（1981）：若 \\(P_t=\\mathrm{E}_t\\sum \\beta^j D_{t+j}\\)（恒定折现），则事后实现的现值 \\(P_t^*\\) 应比 \\(P_t\\) 更抖——因为 \\(P_t\\) 是 \\(P_t^*\\) 的条件期望，方差不等式 \\(\\mathrm{Var}(P)\\le\\mathrm{Var}(P^*)\\)。用实际股利路径构造 \\(P^*\\)，历史价格常常更抖，不等式翻。缺口是：拒绝的是「恒定折现加理性预期加这组股利」，不是拒绝存在 \\(m\\)。时变折现（上一课的回报通道）会放开上界。</p><p>Lucas 树在果实波动很小、 \\(u\\) 接近线性时接近恒定折现，会被同一界限打到；习惯与时变风险厌恶让 \\(m\\) 抖，价格可以比股利更抖。本课不重做那些偏好，只钉界限的假设。</p><p><span class="marginnote">Shiller, <em>AER</em> 71(3), 1981。LeRoy–Porter 几乎同时给出类似方差界。后文对单位根、小样本的批评改变测量，不改变「恒定折现 ⇒ 平滑」的逻辑。</span></p><p><span class="marginnote">直觉类比：\\(P_t\\) 与 \\(P^*\\) 的关系，像你在赛季中途预测某队整季积分，与赛季结束后回填的「真实轨迹」的关系。理性预测线必然比真实轨迹更平缓——因为它平均掉了未知。若你的预测线反而上蹿下跳得比真实轨迹厉害，说明它在追随别的东西，这正是 Shiller 对历史股价做的体检。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在恒定 \\(r\\) 下把 CS 分解的 \\(r\\) 通道关掉，\\(d-p\\) 只含预期 \\(\\Delta d\\)。股利若近单位根，水平的方差界技术上麻烦，但精神仍是：价格不该相对股利流有额外的自由波动。打开 \\(r\\) 通道，价格波动可以来自贴现率消息，Campbell 方差分解把意外回报拆成股利消息减折现率消息——过度波动在会计上就是折现率消息这一项大。</p>',10)),(l(),s(A,null,{default:e(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CONST%5B%22%E6%81%92%E5%AE%9A%E6%8A%98%E7%8E%B0%22%5D%20--%3E%20BND%5B%22Var(P)%20%E2%89%A4%20Var(P*)%22%5D%0A%20%20DATA%5B%22%E4%BB%B7%E6%A0%BC%E6%9B%B4%E6%8A%96%22%5D%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%E6%81%92%E5%AE%9A%20r%22%5D%0A%20%20TIME%5B%22%E6%97%B6%E5%8F%98%20m%22%5D%20--%3E%20OPEN%5B%22%E4%B8%8A%E7%95%8C%E6%94%BE%E5%BC%80%22%5D%0A%20%20REJ%20--%3E%20TIME%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要把 \\(P^*\\) 的构造写成事件研究。那是全样本股利路径的事后现值，信息集是计量经济学家的，不是 \\(t\\) 时刻的 \\(\\mathcal{F}_t\\)。界限用的正是这一点：理性价格是更小信息集上的投影，理应更平滑。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是条件期望的收缩。新信息若只关于股利，价格变动是股利路径的修正，平滑过的对象波动小于对象本身。若新信息主要关于 \\(m\\)（风险厌恶、中介约束、安全资产便利——后课），价格可以大动而股利不动，界限失效。信息课序的美人竞赛提供另一条：公共噪声进入高阶，价格可以跟噪声抖，股利仍平滑——那是对 \\(\\mathbb{P}\\) 下投影的偏离，与时变 \\(m\\) 要靠联合假说区分。",-1)),(l(),s(A,null,{default:e(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PSTAR%5B%22%E4%BA%8B%E5%90%8E%E7%8E%B0%E5%80%BC%20P*%3A%20%E7%94%A8%E5%85%A8%E6%A0%B7%E6%9C%AC%E8%82%A1%E5%88%A9%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20PROJ%5B%22P_t%20%E6%98%AF%20P*%20%E7%9A%84%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20PROJ%20--%3E%20SMOOTHER%5B%22%E7%90%86%E6%80%A7%E4%BB%B7%E6%A0%BC%E5%BA%94%E6%AF%94%20P*%20%E6%9B%B4%E5%B9%B3%E6%BB%91%22%5D%0A%20%20NEWS%5B%22%E6%96%B0%E6%B6%88%E6%81%AF%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20DMSG%5B%22%E8%82%A1%E5%88%A9%E6%B6%88%E6%81%AF%3A%20%E4%BF%AE%E6%AD%A3%E6%9C%AA%E6%9D%A5%E6%9E%9C%E5%AE%9E%22%5D%0A%20%20NEWS%20--%3E%20RMSG%5B%22%E6%8A%98%E7%8E%B0%E7%8E%87%E6%B6%88%E6%81%AF%3A%20%E6%94%B9%E5%8F%98%20m%22%5D%0A%20%20DMSG%20--%3E%20INSIDE%5B%22%E6%B3%A2%E5%8A%A8%E4%BB%8D%E5%9C%A8%E7%95%8C%E5%86%85%22%5D%0A%20%20RMSG%20--%3E%20BREAK%5B%22%E4%BB%B7%E6%A0%BC%E5%A4%A7%E5%8A%A8%E8%80%8C%E8%82%A1%E5%88%A9%E4%B8%8D%E5%8A%A8%2C%20%E7%95%8C%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>与 GS：部分揭示减少的是价格对 \\(\\theta\\) 的敏感，通常让价格更钝而不是更抖。过度波动不像采集不足，更像折现率或高阶噪声。</p><p><span class="marginnote">泡沫项也会加波动。理性泡沫课已写横截失败。Shiller 原文的精神更接近「基本面折现太平滑」，后文把时变折现当成主流修补。</span></p><p><span class="marginnote">常见误区：初学者容易把「过度波动」检验读成「市场无效已被证明」或「泡沫已确诊」。实际上这是一个联合假说检验——被拒绝的是「恒定折现 + 理性预期 + 这组股利过程」的合取，任何一条松开（尤其是时变折现率）都能合法放开方差上界，市场有效性不必被否证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不裁定单位根争论，不重画 1981 年的图。下一课把可预测性落到股利–价格比作为回报预测变量：过度波动的对偶是 \\(d-p\\) 有预测力。两者一起指向时变贴现率，仍不是 CAPM 截面异象。</p><p>后课默认：恒定折现 ⇒ 价格相对事后现值更平滑；观测到的过度波动拒绝恒定 \\(r\\)，不自动拒绝 FTAP 或 EMH。时变 \\(m\\) 是许可的出口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Shiller 界：恒定折现下 \\(\\mathrm{Var}(P)\\le\\mathrm{Var}(P^*)\\)。</li><li>价格更抖，拒绝恒定预期回报，不拒绝存在 \\(m\\)。</li><li>与 \\(d-p\\) 预测回报是同一会计的波动端与预测端。</li><li>出处：Shiller, <em>AER</em> 1981；对照 LeRoy and Porter；Campbell 方差分解。</li></ul>',8))])}const C=n(m,[["render",p]]);export{u as __pageData,C as default};
